final class BadnikRenderers {
 static ResourceLocation texture(String name){return new ResourceLocation("sonicraft","textures/entities/"+name+".png");}
 static void register(){RenderingRegistry.registerEntityRenderingHandler(GroundBadnik.Motobug.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnik.Crabmeat.class,m->new Geo(m));
  RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnik.Caterkiller.class,m->new Geo(m));
  RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnik.Spiny.class,m->new Geo(m));
  RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnik.Splats.class,m->new Geo(m));
  RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnik.BallHog.class,m->new Geo(m));
  RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnik.Roller.class,m->new Geo(m));
  RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnik.BuzzBomber.class,m->new Geo(m));
  RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnik.Batbrain.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(GroundBadnik.Burrobot.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(GroundBadnik.Rhinobot.class,m->new Rhino(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV2.JawsBadnik.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV2.Woodrow.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV2.Grabber.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV2.Grounder.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV2.Coconuts.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV2.Bumpalo.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV3.Aquis.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV3.Buzzer.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV3.BombBadnik.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV3.CrawlBadnik.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV3.EggFlapper.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV3.Flasher.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV3.Octus.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV3.SpikesBadnik.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV3.Rattlekiller.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV3.Rexon.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV3.Shutterbug.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV3.Iwamodoki.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV4.Newtron.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV4.Tubinaut.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV4.Gohla.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(AdditionalBadnikV4.EggPawnBunny.class,m->new Geo(m));RenderingRegistry.registerEntityRenderingHandler(FreedAnimal.Flicky.class,m->new Animal(m,new FlickyModel112(),"flicky"));RenderingRegistry.registerEntityRenderingHandler(FreedAnimal.Pocky.class,m->new Animal(m,new PockyModel112(),"pocky"));}
 static class Model extends AnimatedGeoModel<GroundBadnik>{
  GeoModel prepared;
  @Override public GeoModel getModel(ResourceLocation location){GeoModel m=super.getModel(location);if(m!=prepared){GeoCompatibility.prepare(m);prepared=m;}return m;}
  @Override public void setLivingAnimations(GroundBadnik e,Integer id,software.bernie.geckolib3.core.event.predicate.AnimationEvent event){super.setLivingAnimations(e,id,event);if(event==null)return;java.util.List<software.bernie.geckolib3.model.provider.data.EntityModelData> data=event.getExtraDataOfType(software.bernie.geckolib3.model.provider.data.EntityModelData.class);software.bernie.geckolib3.core.processor.IBone head=getAnimationProcessor().getBone("head");if(head!=null&&!data.isEmpty())CharacterRenderers.look(head,data.get(0).headPitch,data.get(0).netHeadYaw);}
  @Override public ResourceLocation getModelLocation(GroundBadnik e){return new ResourceLocation("sonicraft","geo/"+e.definition().geo+".geo.json");}
  @Override public ResourceLocation getTextureLocation(GroundBadnik e){return texture(e.definition().id);}
  @Override public ResourceLocation getAnimationFileLocation(GroundBadnik e){return new ResourceLocation("sonicraft","animations/"+e.definition().geo+".animation.json");}
 }
 static void glowStart(){GlStateManager.enableBlend();GlStateManager.blendFunc(GlStateManager.SourceFactor.ONE,GlStateManager.DestFactor.ONE);GlStateManager.disableLighting();GlStateManager.depthMask(false);OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit,240,240);GlStateManager.color(1,1,1,1);}
 static void glowEnd(float x,float y){OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit,x,y);GlStateManager.depthMask(true);GlStateManager.enableLighting();GlStateManager.disableBlend();GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA,GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);GlStateManager.color(1,1,1,1);}
 static class Geo extends GeoEntityRenderer<GroundBadnik>{Geo(RenderManager m){super(m,new Model());shadowSize=.5f;addLayer(new GeoLayerRenderer<GroundBadnik>(this){@Override public boolean shouldCombineTextures(){return false;}@Override public void render(GroundBadnik e,float swing,float amount,float partial,float age,float yaw,float pitch,Color color){if(!(e instanceof GroundBadnik.Motobug)||e.isInvisible())return;float x=OpenGlHelper.lastBrightnessX,y=OpenGlHelper.lastBrightnessY;glowStart();try{Minecraft.getMinecraft().getTextureManager().bindTexture(texture("motobug_glow"));Model model=(Model)modelProvider;getRenderer().render(model.getModel(model.getModelLocation(e)),e,partial,1,1,1,1);}finally{glowEnd(x,y);}}});}}
 static class Rhino extends RenderLiving<GroundBadnik.Rhinobot>{Rhino(RenderManager m){super(m,new RhinobotModel112(),.5f);addLayer(new LayerRenderer<GroundBadnik.Rhinobot>(){public boolean shouldCombineTextures(){return false;}public void doRenderLayer(GroundBadnik.Rhinobot e,float swing,float amount,float partial,float age,float yaw,float pitch,float scale){if(e.isInvisible())return;float x=OpenGlHelper.lastBrightnessX,y=OpenGlHelper.lastBrightnessY;glowStart();try{bindTexture(texture("rhinobot_glow"));mainModel.render(e,swing,amount,age,yaw,pitch,scale);}finally{glowEnd(x,y);}}});}@Override protected ResourceLocation getEntityTexture(GroundBadnik.Rhinobot e){return texture("rhinobot");}}
 static class Animal extends RenderLiving<FreedAnimal>{final String id;Animal(RenderManager m,ModelBase model,String id){super(m,model,.2f);this.id=id;}@Override protected ResourceLocation getEntityTexture(FreedAnimal e){return texture(id);}}
}
